def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.
    """
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}
    abridores = set(pares.values())

    for caracter in s:
        if caracter in abridores:
            pila.append(caracter)
        elif caracter in pares:
            if not pila or pila[-1] != pares[caracter]:
                return False
            pila.pop()

    return not pila

def mediana(nums):
    if not nums:
        return None
    nums = sorted(nums)
    n = len(nums)
    if n % 2 == 0:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2
    else:
        return nums[n // 2]

