def dedup(lista):
    seen = set()
    result = []
    for item in lista:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def anidar(plano: dict) -> dict:
    """Convierte un diccionario con claves anidadas (ej: 'a.b') en un diccionario anidado.

    Args:
        plano: Diccionario con claves separadas por puntos (ej: {'a.b': 1}).

    Returns:
        Diccionario anidado (ej: {'a': {'b': 1}}).
    """
    resultado = {}
    for clave, valor in plano.items():
        partes = clave.split('.')
        actual = resultado
        for parte in partes[:-1]:
            if parte not in actual:
                actual[parte] = {}
            actual = actual[parte]
        actual[partes[-1]] = valor
    return resultado

