def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a una cadena legible usando múltiplos de 1024.

    Args:
        n: Número de bytes (entero no negativo).

    Returns:
        Una cadena con el valor formateado (ej: '1.5 KB', '2 GB').
    """
    if n == 0:
        return "0 B"

    unidades = ["B", "KB", "MB", "GB"]
    valor = float(n)

    for i in range(len(unidades)):
        if valor < 1024:
            break
        valor /= 1024

    if unidades[i] == "B":
        return f"{int(valor)} B"
    else:
        return f"{valor:.1f} {unidades[i]}"

def parsear_query(s: str) -> dict:
    if not s:
        return {}
    result = {}
    for pair in s.split('&'):
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key] = value
        else:
            result[pair] = ''
    return result

def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    filas = len(grid)
    columnas = len(grid[0])
    islas = 0

    def bfs(fila, columna):
        queue = [(fila, columna)]
        grid[fila][columna] = 0

        while queue:
            actual_fila, actual_columna = queue.pop(0)

            vecinos = [
                (actual_fila - 1, actual_columna),
                (actual_fila + 1, actual_columna),
                (actual_fila, actual_columna - 1),
                (actual_fila, actual_columna + 1),
            ]

            for vecino_fila, vecino_columna in vecinos:
                if (
                    0 <= vecino_fila < filas
                    and 0 <= vecino_columna < columnas
                    and grid[vecino_fila][vecino_columna] == 1
                ):
                    grid[vecino_fila][vecino_columna] = 0
                    queue.append((vecino_fila, vecino_columna))

    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1:
                islas += 1
                bfs(i, j)

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # borrado
                    dp[i][j - 1],    # inserción
                    dp[i - 1][j - 1] # sustitución
                )
    return dp[m][n]

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not any(c.isupper() for c in p):
        return False
    if not any(c.islower() for c in p):
        return False
    if not any(c.isdigit() for c in p):
        return False
    if not any(not c.isalnum() for c in p):
        return False
    return True

